def check_N2_existence(p):
    # Check if there exist C1, C2 such that C1 + C2 = 0, and C1 != 0, C2 != 0
    # C1 must be in {-2p, -p, p, 2p}
    # C2 must be in {-2*p**2, -p**2, p**2, 2*p**2}

    C1_options = [-2*p, -p, p, 2*p]
    C2_options = [-2*p**2, -p**2, p**2, 2*p**2]

    found = False
    for C1 in C1_options:
        if C1 == 0:
            continue
        C2_required = -C1

        for C2 in C2_options:
            if C2 == 0:
                continue
            if C2 == C2_required:
                print(f"Found solution for p={p}: C1={C1}, C2={C2}")
                found = True
                return True
    return False

print("Testing p=1/2:")
check_N2_existence(1/2)
print("\nTesting p=1:")
check_N2_existence(1)
print("\nTesting p=2:")
check_N2_existence(2)
